package es.tentuplaza.identity.emailotp;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.keycloak.models.RealmModel;
import org.keycloak.models.RoleModel;

/** Validate the exact snapshot generated by an integration fixture before using it. */
class AuthorizationRegistryContractTest {
  @Test
  @EnabledIfSystemProperty(named = "tentu.authorization.registry", matches = ".+")
  void generatedRegistryCanBeConsumedByRegistration() throws Exception {
    String json = Files.readString(Path.of(System.getProperty("tentu.authorization.registry")));
    var realm = mock(RealmModel.class);
    var interested = mock(RoleModel.class);
    when(realm.getAttribute(AuthorizationResourceFactory.ACTIVE)).thenReturn(json);
    when(realm.getAttribute(RegistrationPolicy.DEFAULT_ROLE)).thenReturn("interesado");
    when(realm.getRole("interesado")).thenReturn(interested);
    var registry = assertDoesNotThrow(() -> AuthorizationResourceFactory.read(realm),
        "The generated authorization snapshot must match the provider's wire contract");
    assertDoesNotThrow(() -> AuthorizationResourceFactory.validate(registry));
    assertSame(interested, RegistrationPolicy.defaultRole(realm));
  }
}
